from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def extract_paren_groups(s):
        groups = []
        group = ''
        open_count = 0

        for char in s:
            if char == '(':
                open_count += 1
            elif char == ')':
                open_count -= 1

            group += char

            if open_count == 0:
                groups.append(group)
                group = ''

        return groups

    extracted_groups = extract_paren_groups(paren_string.replace(' ', ''))
    return extracted_groups

# Test the function
